sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Add your code here

	if (current.closed_by.nil())
		current.closed_by = gs.getUserID();
	if (current.closed_at.nil())
		current.closed_at = new GlideDateTime().getDisplayValue();

	var dataChange = current.opened_at.changes() || (current.closed_at.changes() && !current.isValidField("resolved_at"));
	var opened = new GlideDateTime(current.opened_at.getDisplayValueInternal());
	var closed = new GlideDateTime(current.closed_at.getDisplayValueInternal());

	if (dataChange || current.business_duration.nil())
		current.business_duration = GlideDateTime.subtract(opened, closed);

})(current, previous);
